import{_ as e,o as l,c as d,a0 as a}from"./chunks/framework.Bmhw_dvp.js";const f=JSON.parse('{"title":"","description":"","frontmatter":{},"headers":[],"relativePath":"page-4.md","filePath":"page-4.md"}'),n={name:"page-4.md"};function o(i,t,s,c,g,r){return l(),d("div",null,[...t[0]||(t[0]=[a('<h3 id="变量类型" tabindex="-1">变量类型 <a class="header-anchor" href="#变量类型" aria-label="Permalink to &quot;变量类型&quot;">​</a></h3><table tabindex="0"><thead><tr><th style="text-align:left;">类型</th><th style="text-align:left;">标识符</th><th style="text-align:left;">占字节数</th><th style="text-align:left;">数值范围/有效位数</th></tr></thead><tbody><tr><td style="text-align:left;">整型</td><td style="text-align:left;"><code>short</code></td><td style="text-align:left;">2 (16位)</td><td style="text-align:left;"><code>-2^15 ~ 2^15 - 1</code></td></tr><tr><td style="text-align:left;">整型</td><td style="text-align:left;"><code>int</code></td><td style="text-align:left;">4 (32位)</td><td style="text-align:left;"><code>-2^31 ~ 2^31 - 1</code></td></tr><tr><td style="text-align:left;">整型</td><td style="text-align:left;"><code>long</code></td><td style="text-align:left;">4 (32位)</td><td style="text-align:left;"><code>-2^31 ~ 2^31 - 1</code></td></tr><tr><td style="text-align:left;">整型</td><td style="text-align:left;"><code>long long</code></td><td style="text-align:left;">8 (64位)</td><td style="text-align:left;"><code>-2^63 ~ 2^63 - 1</code></td></tr><tr><td style="text-align:left;">浮点型</td><td style="text-align:left;"><code>float</code></td><td style="text-align:left;">4 (32位)</td><td style="text-align:left;">6-7位有效数字</td></tr><tr><td style="text-align:left;">浮点型</td><td style="text-align:left;"><code>double</code></td><td style="text-align:left;">8 (64位)</td><td style="text-align:left;">15-16位有效数字</td></tr><tr><td style="text-align:left;">浮点型</td><td style="text-align:left;"><code>long double</code></td><td style="text-align:left;">16 (128位)</td><td style="text-align:left;">18-19位有效数字</td></tr><tr><td style="text-align:left;">字符型</td><td style="text-align:left;"><code>char</code></td><td style="text-align:left;">1 (8位)</td><td style="text-align:left;"><code>-128 ~ 127</code> 或 <code>0 ~ 255</code></td></tr><tr><td style="text-align:left;">布尔型</td><td style="text-align:left;"><code>bool</code></td><td style="text-align:left;">1 (8位)</td><td style="text-align:left;"><code>true</code> 或 <code>false</code>（0或1）</td></tr><tr><td style="text-align:left;">无类型</td><td style="text-align:left;"><code>void</code></td><td style="text-align:left;">无</td><td style="text-align:left;">无</td></tr></tbody></table><h3 id="类型修饰符" tabindex="-1">类型修饰符 <a class="header-anchor" href="#类型修饰符" aria-label="Permalink to &quot;类型修饰符&quot;">​</a></h3><table tabindex="0"><thead><tr><th style="text-align:left;">修饰符</th><th style="text-align:left;">说明</th><th style="text-align:left;">示例</th></tr></thead><tbody><tr><td style="text-align:left;"><code>signed</code></td><td style="text-align:left;">有符号类型（默认）</td><td style="text-align:left;"><code>signed int</code></td></tr><tr><td style="text-align:left;"><code>unsigned</code></td><td style="text-align:left;">无符号类型，表示非负数</td><td style="text-align:left;"><code>unsigned int</code></td></tr><tr><td style="text-align:left;"><code>short</code></td><td style="text-align:left;">短整型，通常 2 字节</td><td style="text-align:left;"><code>short int</code></td></tr><tr><td style="text-align:left;"><code>long</code></td><td style="text-align:left;">长整型，通常 4 或 8 字节</td><td style="text-align:left;"><code>long int</code></td></tr><tr><td style="text-align:left;"><code>long long</code></td><td style="text-align:left;">更长整型，通常 8 字节</td><td style="text-align:left;"><code>long long int</code></td></tr><tr><td style="text-align:left;"><code>const</code></td><td style="text-align:left;">常量修饰符，值不可修改</td><td style="text-align:left;"><code>const int N = 10;</code></td></tr><tr><td style="text-align:left;"><code>volatile</code></td><td style="text-align:left;">告诉编译器该变量可能被意外修改，不优化</td><td style="text-align:left;"><code>volatile int flag;</code></td></tr><tr><td style="text-align:left;"><code>static</code></td><td style="text-align:left;">静态存储期，生命周期贯穿程序运行</td><td style="text-align:left;"><code>static int cnt;</code></td></tr><tr><td style="text-align:left;"><code>extern</code></td><td style="text-align:left;">声明外部定义的变量或函数</td><td style="text-align:left;"><code>extern int x;</code></td></tr><tr><td style="text-align:left;"><code>register</code></td><td style="text-align:left;">建议将变量存放在寄存器中（已废弃）</td><td style="text-align:left;"><code>register int i;</code></td></tr></tbody></table><h3 id="函数修饰符" tabindex="-1">函数修饰符 <a class="header-anchor" href="#函数修饰符" aria-label="Permalink to &quot;函数修饰符&quot;">​</a></h3><table tabindex="0"><thead><tr><th style="text-align:left;">修饰符</th><th style="text-align:left;">说明</th><th style="text-align:left;">示例</th></tr></thead><tbody><tr><td style="text-align:left;"><code>inline</code></td><td style="text-align:left;">建议编译器将函数体展开，消除函数调用开销（仅建议，编译器可忽略）</td><td style="text-align:left;"><code>inline int add(int a, int b) { return a + b; }</code></td></tr><tr><td style="text-align:left;"><code>static</code></td><td style="text-align:left;">将函数的作用域限制在当前文件（内部链接），或类内静态成员函数</td><td style="text-align:left;"><code>static void helper() { ... }</code></td></tr><tr><td style="text-align:left;"><code>virtual</code></td><td style="text-align:left;">声明虚函数，用于实现多态（运行时绑定）</td><td style="text-align:left;"><code>virtual void draw() { ... }</code></td></tr><tr><td style="text-align:left;"><code>const</code></td><td style="text-align:left;">声明常成员函数，承诺不修改对象成员（除 <code>mutable</code> 成员外）</td><td style="text-align:left;"><code>int get() const { return x; }</code></td></tr><tr><td style="text-align:left;"><code>override</code></td><td style="text-align:left;">（C++11）显式表示重写基类虚函数，编译时检查</td><td style="text-align:left;"><code>void draw() override { ... }</code></td></tr><tr><td style="text-align:left;"><code>final</code></td><td style="text-align:left;">（C++11）禁止虚函数被继续重写，或禁止类被继承</td><td style="text-align:left;"><code>void draw() final { ... }</code> / <code>class A final { ... };</code></td></tr><tr><td style="text-align:left;"><code>noexcept</code></td><td style="text-align:left;">（C++11）声明函数不会抛出异常，编译器可优化</td><td style="text-align:left;"><code>void func() noexcept { ... }</code></td></tr><tr><td style="text-align:left;"><code>friend</code></td><td style="text-align:left;">声明友元函数或友元类，允许访问类的私有成员</td><td style="text-align:left;"><code>friend void print(const A&amp; a);</code></td></tr><tr><td style="text-align:left;"><code>explicit</code></td><td style="text-align:left;">禁止构造函数或转换运算符的隐式类型转换</td><td style="text-align:left;"><code>explicit A(int x) { ... }</code></td></tr><tr><td style="text-align:left;"><code>constexpr</code></td><td style="text-align:left;">（C++11）声明常量表达式函数，编译期求值</td><td style="text-align:left;"><code>constexpr int square(int x) { return x * x; }</code></td></tr><tr><td style="text-align:left;"><code>mutable</code></td><td style="text-align:left;">允许常成员函数修改该成员（常用于缓存、锁等）</td><td style="text-align:left;"><code>mutable int cache;</code></td></tr><tr><td style="text-align:left;"><code>static_assert</code></td><td style="text-align:left;">（C++11）编译期断言，条件不成立则编译失败</td><td style="text-align:left;"><code>static_assert(sizeof(int) == 4, &quot;int must be 4 bytes&quot;);</code></td></tr></tbody></table>',6)])])}const y=e(n,[["render",o]]);export{f as __pageData,y as default};
